/**
 * SFX plan - every hit is anchored to a narrated word (at(phrase, word)) or a scene start.
 * name -> public/audio/sfx/<name>.wav   (generated by scripts/build_audio.py)
 * Keep volumes low: the voice must always stay on top.
 */
import { at, endAt, SCENES, TRANSITIONS, COUNTDOWN_START } from './timing';

export type Sfx = { t: number; name: string; v: number };
const list: Sfx[] = [];
const add = (t: number, name: string, v = 0.35) => list.push({ t: Math.max(0, t), name, v });
const keys = (a: number, b: number, n: number, v = 0.3) => { for (let i = 0; i < n; i++) add(a + ((b - a) * i) / Math.max(1, n - 1), 'key', v * (0.8 + 0.2 * ((i * 7) % 3) / 2)); };

// scene transitions
const tName: Record<string, [string, number]> = { whip: ['whoosh', 0.45], zoom: ['whoosh', 0.32], slideUp: ['swipe', 0.4], wipe: ['swipe', 0.35], blur: ['rise', 0.3], slideLeft: ['swipe', 0.4] };
TRANSITIONS.forEach((k, i) => add(SCENES[i + 1].start - 0.08, tName[k][0], tName[k][1]));

// HOOK
add(0.05, 'impact', 0.5); add(at(0, 4) + 0.15, 'click', 0.45); add(at(0, 6), 'pop', 0.35); add(at(0, 6) + 1.0, 'tick', 0.3);
for (let i = 0; i < 5; i++) add(at(1, 3) + i * 0.3, 'pop', 0.32); add(at(2, 2), 'digital', 0.3); add(at(2, 5), 'success', 0.3);
// PROBLEM
add(at(3, 0), 'pop', 0.35); add(at(4, 2), 'whoosh', 0.3); add(at(4, 3), 'impact', 0.55); add(at(5, 0), 'pop', 0.3); add(at(5, 2), 'pop', 0.3); add(at(5, 4), 'pop', 0.35); add(at(6, 2), 'pop', 0.4);
// STEP 1
add(at(7, 0), 'pop', 0.35); add(at(8, 0) + 0.15, 'click', 0.5); add(at(9, 0), 'whoosh', 0.3); keys(at(9, 3), endAt(9, 4) + 0.15, 14); add(at(9, 6), 'digital', 0.3);
// STEP 2
add(at(10, 0), 'pop', 0.35); add(at(11, 0), 'digital', 0.3); add(at(11, 4), 'tick', 0.35); add(at(11, 4) + 0.8, 'success', 0.35); add(at(12, 0), 'whoosh', 0.35); add(at(13, 2), 'pop', 0.4);
// STEP 3
add(at(14, 0), 'pop', 0.35); add(at(15, 0), 'pop', 0.35); add(at(15, 4), 'rise', 0.25);
for (let i = 0; i < 4; i++) add(at(15, 6) + i * ((endAt(15) - at(15, 6)) / 4), 'tick', 0.3);
add(at(16, 0), 'pop', 0.35); for (let i = 0; i < 3; i++) add(at(16, 3) + 0.55 * (i + 1), 'tick', 0.3);
// QUIZ
add(at(17, 0), 'pop', 0.4); add(at(18, 1), 'pop', 0.35); add(at(19, 0), 'pop', 0.35);
for (let i = 0; i < 3; i++) add(COUNTDOWN_START + i, 'tick', 0.5); add(at(21, 0), 'pop', 0.3);
// ANSWER
add(at(22, 0), 'pop', 0.3); add(at(23, 0), 'ding', 0.55); add(at(23, 0) + 0.05, 'success', 0.3); add(at(24, 1), 'whoosh', 0.28); add(at(25, 1), 'whoosh', 0.28);
// HARDWARE
add(at(26, 0), 'pop', 0.3); add(at(27, 0), 'pop', 0.35); add(at(27, 3), 'pop', 0.4); add(at(28, 0), 'whoosh', 0.3); add(at(28, 2), 'whoosh', 0.3);
add(at(29, 0), 'digital', 0.4); add(at(29, 0) + 1.0, 'digital', 0.28); add(at(30, 0), 'success', 0.4);
// PAYOFF
add(at(31, 0), 'impact', 0.45); keys(at(32, 0), at(32, 1) + 0.15, 10); keys(at(32, 3), endAt(32, 3) + 0.2, 12); add(at(32, 4), 'click', 0.5); add(at(32, 5), 'digital', 0.35);
for (let i = 0; i < 4; i++) add(at(33, 0) + i * ((endAt(33) - at(33, 0) - 0.3) / 3), 'tick', 0.3); add(at(33, 3), 'success', 0.4);
// BONUS
add(at(34, 0), 'pop', 0.35); add(at(35, 0) - 0.3, 'pop', 0.25); add(at(35, 0) + 0.3, 'pop', 0.3); add(at(35, 5), 'pop', 0.3); add(at(35, 7), 'click', 0.45); add(at(36, 0), 'whoosh', 0.3); add(at(36, 0) + 1.9, 'ding', 0.4);
// RECAP
for (let i = 0; i < 6; i++) add(70.45 + i * 0.4, 'pop', 0.3); add(at(37, 3), 'pop', 0.4);
// CTA
add(at(38, 0), 'impact', 0.4); keys(at(38, 1), at(38, 1) + 0.5, 4, 0.35); add(at(38, 3), 'click', 0.5); add(at(39, 0), 'success', 0.45); add(at(39, 0) + 0.1, 'pop', 0.35);

export const SFX: Sfx[] = list.sort((a, b) => a.t - b.t);
